# Figures in vignettes/figs and vignettes/articles/figs are generated by
# vignettes/precompute.R. A figure no document refers to is dead weight in the
# tarball (vignettes/figs ships) or on the website (Plan 04 PERF-12 item 6).
# The source tree is not available under R CMD check, so this runs only from
# a source checkout.

vignette_dir <- function() {
  dir <- test_path("..", "..", "vignettes")
  skip_if_not(dir.exists(dir), "vignette sources are not available")
  dir
}

figure_references <- function(docs) {
  text <- unlist(lapply(docs, readLines, warn = FALSE))
  unique(basename(unlist(regmatches(
    text,
    gregexpr("figs/[A-Za-z0-9._-]+\\.png", text)
  ))))
}

test_that("every vignette figure is used, and every used figure exists", {
  vig <- vignette_dir()
  for (sub in c(".", "articles")) {
    dir <- file.path(vig, sub)
    docs <- list.files(dir, pattern = "\\.Rmd$", full.names = TRUE)
    figs <- list.files(file.path(dir, "figs"), pattern = "\\.png$")
    used <- figure_references(docs)
    expect_identical(
      sort(setdiff(figs, used)),
      character(),
      info = paste(dir, "orphans")
    )
    expect_identical(
      sort(setdiff(used, figs)),
      character(),
      info = paste(dir, "missing")
    )
  }
})
